{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */
import fs from 'node:fs'
import { parseSheet } from './sheet.js'
import { parseFormula, collectDeps } from './formula.js'
import { Evaluator, formatValue } from './eval.js'

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'values' && args[0] !== 'deps')) {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}

let cells
try {
  cells = parseSheet(fs.readFileSync(0, 'utf8'))
} catch (e) {
  if (e && e.sheetError) {
    process.stderr.write(e.message + '\n')
    process.exit(2)
  }
  throw e
}

let out = ''
if (args[0] === 'values') {
  const ev = new Evaluator(cells)
  for (const c of cells) out += `${c.addr}=${formatValue(ev.valueOf(c.key))}\n`
} else {
  for (const c of cells) {
    let line = `${c.addr}:`
    if (c.content.startsWith('=')) {
      const tree = parseFormula(c.content.slice(1))
      if (tree) for (const d of collectDeps(tree)) line += ' ' + d
    }
    out += line + '\n'
  }
}
process.stdout.write(out)
"}

