{"file_path":"src/eval.js","content":"import { parseFormula } from './formula.js'
import { keyOf } from './address.js'

class Err {
  constructor(token) { this.token = token }
}
const E = {
  div: new Err('#DIV/0!'),
  ref: new Err('#REF!'),
  value: new Err('#VALUE!'),
  cycle: new Err('#CYCLE!'),
  name: new Err('#NAME?'),
  err: new Err('#ERR!'),
}
const TOKENS = new Map(Object.values(E).map((e) => [e.token, e]))

export function formatValue(v) {
  if (v instanceof Err) return v.token
  if (typeof v === 'boolean') return v ? 'TRUE' : 'FALSE'
  if (typeof v === 'number') return String(Number(v.toPrecision(10)))
  return v
}

function rank(v) {
  return typeof v === 'number' ? 0 : typeof v === 'string' ? 1 : 2
}

function cmpStr(a, b) {
  const x = Array.from(a, (c) => c.codePointAt(0))
  const y = Array.from(b, (c) => c.codePointAt(0))
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) if (x[i] !== y[i]) return x[i] < y[i] ? -1 : 1
  return x.length === y.length ? 0 : x.length < y.length ? -1 : 1
}

function compare(a, b) {
  const ra = rank(a), rb = rank(b)
  if (ra !== rb) return ra < rb ? -1 : 1
  if (ra === 1) return cmpStr(a, b)
  const x = Number(a), y = Number(b)
  return x < y ? -1 : x > y ? 1 : 0
}

function fin(n) {
  return Number.isFinite(n) ? n : E.div
}

/** Converts a non-error value to a number, or #VALUE!. */
function num(v) {
  if (typeof v === 'number') return v
  if (typeof v === 'boolean') return v ? 1 : 0
  return E.value
}

export class Evaluator {
  constructor(cells) {
    this.cells = new Map(cells.map((c) => [c.key, c]))
    this.memo = new Map()
    this.stack = new Set()
    this.trees = new Map()
  }

  valueOf(key) {
    const cell = this.cells.get(key)
    if (!cell) return 0
    if (this.memo.has(key)) return this.memo.get(key)
    if (this.stack.has(key)) return E.cycle
    this.stack.add(key)
    let v
