{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */
import fs from 'node:fs'
import { parseSheet } from './sheet.js'
import { parseFormula, collectDeps } from './formula.js'
import { Evaluator, formatValue } from './eval.js'

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'values' && args[0] !== 'deps')) {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}

let cells
try {
  cells = parseSheet(fs.readFileSync(0, 'utf8'))
} catch (e) {
  if (e && e.sheetError) {
    process.stderr.write(e.message + '\n')
    process.exit(2)
  }
  throw e
}

let out = ''
if (args[0] === 'values') {
  const ev = new Evaluator(cells)
  for (const c of cells) out += `${c.addr}=${formatValue(ev.valueOf(c.key))}\n`
} else {
  for (const c of cells) {
    let line = `${c.addr}:`
    if (c.content.startsWith('=')) {
      const tree = parseFormula(c.content.slice(1))
      if (tree) for (const d of collectDeps(tree)) line += ' ' + d
    }
    out += line + '\n'
  }
}
process.stdout.write(out)
"}

{"file_path":"src/sheet.js","content":"import { parseAddress } from './address.js'

function fail(msg) {
  const e = new Error(msg)
  e.sheetError = true
  return e
}

/** Parses the sheet text into cells sorted by column then row. */
export function parseSheet(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const seen = new Set()
  const cells = []
  lines.forEach((raw, i) => {
    const line = raw.replace(/^[ \t]+/, '')
    if (line === '' || line[0] === '#') return
    const m = /^([^ \t]*)[ \t]*([\s\S]*)$/.exec(line)
    const addr = m[1].toUpperCase()
    const content = m[2]
    const p = parseAddress(addr)
    if (!p) throw fail(`error: line ${i + 1}: invalid cell address ${addr}`)
    if (seen.has(p.key)) throw fail(`error: line ${i + 1}: cell ${addr} is declared twice`)
    seen.add(p.key)
    cells.push({ addr, key: p.key, col: p.col, row: p.row, content })
  })
  cells.sort((a, b) => a.col - b.col || a.row - b.row)
  return cells
}
"}

{"file_path":"src/address.js","content":"/** Column index: A..Z = 1..26, AA..ZZ = 27..702. */
export function colIndex(letters) {
  if (letters.length === 1) return letters.charCodeAt(0) - 64
  return 26 + (letters.charCodeAt(0) - 65) * 26 + (letters.charCodeAt(1) - 64)
}

export function keyOf(col, row) {
  return col * 1000 + row
}

/** Returns {col,row,key} for an in-range address (any case), else null. */
export function parseAddress(s) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(s)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const col = colIndex(m[1].toUpperCase())
  return { col, row, key: keyOf(col, row) }
}
"}

{"file_path":"src/formula.js","content":"import { parseAddress } from './address.js'

const CMP = ['=', '<>', '<', '<=', '>', '>=']

function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const c = s[i]
    if (c === ' ' || c === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) {
      toks.push({ t: 'num', v: Number(m[0]) })
      i += m[0].length
    } else if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) {
      toks.push({ t: 'word', v: m[0].toUpperCase() })
      i += m[0].length
    } else if (s.startsWith('<>', i) || s.startsWith('<=', i) || s.startsWith('>=', i)) {
      toks.push({ t: 'op', v: s.slice(i, i + 2) })
      i += 2
    } else if ('^*/+-=<>(),:'.includes(c)) {
      toks.push({ t: 'op', v: c })
      i++
    } else return null
  }
  return toks
}

class Bad extends Error {}

/** Returns a syntax tree or null when the grammar rejects the body. */
export function parseFormula(body) {
  const toks = tokenize(body)
  if (!toks) return null
  let p = 0
  const peekOp = (v) => p < toks.length && toks[p].t === 'op' && toks[p].v === v

  function comparison() {
    let l = additive()
    while (p < toks.length && toks[p].t === 'op' && CMP.includes(toks[p].v)) {
      const op = toks[p++].v
      l = { k: 'bin', op, l, r: additive() }
    }
    return l
  }
  function additive() {
    let l = term()
    while (peekOp('+') || peekOp('-')) {
      const op = toks[p++].v
      l = { k: 'bin', op, l, r: term() }
    }
    return l
  }
  function term() {
    let l = power()
    while (peekOp('*') || peekOp('/')) {
      const op = toks[p++].v
      l = { k: 'bin', op, l, r: power() }
    }
    return l
  }
  function power() {
    const l = unary()
    if (peekOp('^')) {
      p++
      return { k: 'bin', op: '^', l, r: power() }
    }
    return l
  }
  function unary() {
    if (peekOp('-') || peekOp('+')) {
      const op = toks[p++].v
      return { k: 'un', op, e: unary() }
    }
    return primary()
  }
  function primary() {
    const t = toks[p]
    if (!t) throw new Bad()
    if (t.t === 'num') { p++; return { k: 'num', v: t.v } }
    if (t.t === 'op') {
      if (t.v !== '(') throw new Bad()
      p++
      const e = comparison()
      if (!peekOp(')')) throw new Bad()
      p++
      return { k: 'paren', e }
    }
    p++
    if (peekOp('(')) {
      p++
      const args = []
      if (peekOp(')')) { p++ } else {
        for (;;) {
          args.push(comparison())
          if (peekOp(',')) { p++; continue }
          if (peekOp(')')) { p++; break }
          throw new Bad()
        }
      }
      return { k: 'call', name: t.v, args }
    }
    if (peekOp(':')) {
      p++
      const u = toks[p]
      if (!u || u.t !== 'word') throw new Bad()
      p++
      if (peekOp('(')) throw new Bad()
      return { k: 'range', a: parseAddress(t.v), b: parseAddress(u.v) }
    }
    if (t.v === 'TRUE') return { k: 'bool', v: true }
    if (t.v === 'FALSE') return { k: 'bool', v: false }
    return { k: 'ref', a: parseAddress(t.v) }
  }

  try {
    const tree = comparison()
    if (p !== toks.length) return null
    return tree
  } catch (e) {
    if (e instanceof Bad) return null
    throw e
  }
}

/** Distinct in-range addresses named by the tree, as sorted strings. */
export function collectDeps(tree) {
  const set = new Map()
  const add = (col, row) => set.set(col * 1000 + row, { col, row })
  ;(function walk(n) {
    switch (n.k) {
      case 'ref': if (n.a) add(n.a.col, n.a.row); break
      case 'range':
        if (n.a && n.b) {
          for (let c = Math.min(n.a.col, n.b.col); c <= Math.max(n.a.col, n.b.col); c++)
            for (let r = Math.min(n.a.row, n.b.row); r <= Math.max(n.a.row, n.b.row); r++) add(c, r)
        }
        break
      case 'bin': walk(n.l); walk(n.r); break
      case 'un': case 'paren': walk(n.e); break
      case 'call': n.args.forEach(walk); break
    }
  })(tree)
  return [...set.values()]
    .sort((a, b) => a.col - b.col || a.row - b.row)
    .map(({ col, row }) => colName(col) + row)
}

export function colName(col) {
  if (col <= 26) return String.fromCharCode(64 + col)
  const x = col - 27
  return String.fromCharCode(65 + Math.floor(x / 26), 65 + (x % 26))
}
"}

{"file_path":"src/eval.js","content":"import { parseFormula } from './formula.js'
import { keyOf } from './address.js'

class Err {
  constructor(token) { this.token = token }
}
const E = {
  div: new Err('#DIV/0!'),
  ref: new Err('#REF!'),
  value: new Err('#VALUE!'),
  cycle: new Err('#CYCLE!'),
  name: new Err('#NAME?'),
  err: new Err('#ERR!'),
}
const TOKENS = new Map(Object.values(E).map((e) => [e.token, e]))

export function formatValue(v) {
  if (v instanceof Err) return v.token
  if (typeof v === 'boolean') return v ? 'TRUE' : 'FALSE'
  if (typeof v === 'number') return String(Number(v.toPrecision(10)))
  return v
}

function rank(v) {
  return typeof v === 'number' ? 0 : typeof v === 'string' ? 1 : 2
}

function cmpStr(a, b) {
  const x = Array.from(a, (c) => c.codePointAt(0))
  const y = Array.from(b, (c) => c.codePointAt(0))
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) if (x[i] !== y[i]) return x[i] < y[i] ? -1 : 1
  return x.length === y.length ? 0 : x.length < y.length ? -1 : 1
}

function compare(a, b) {
  const ra = rank(a), rb = rank(b)
  if (ra !== rb) return ra < rb ? -1 : 1
  if (ra === 1) return cmpStr(a, b)
  const x = Number(a), y = Number(b)
  return x < y ? -1 : x > y ? 1 : 0
}

function fin(n) {
  return Number.isFinite(n) ? n : E.div
}

/** Converts a non-error value to a number, or #VALUE!. */
function num(v) {
  if (typeof v === 'number') return v
  if (typeof v === 'boolean') return v ? 1 : 0
  return E.value
}

export class Evaluator {
  constructor(cells) {
    this.cells = new Map(cells.map((c) => [c.key, c]))
    this.memo = new Map()
    this.stack = new Set()
    this.trees = new Map()
  }

  valueOf(key) {
    const cell = this.cells.get(key)
    if (!cell) return 0
    if (this.memo.has(key)) return this.memo.get(key)
    if (this.stack.has(key)) return E.cycle
    this.stack.add(key)
    let v
    const c = cell.content
    if (c.startsWith('=')) {
      const tree = parseFormula(c.slice(1))
      v = tree ? this.ev(tree) : E.err
    } else if (c === '') v = 0
    else if (/^-?[0-9]+(\.[0-9]+)?$/.test(c)) v = Number(c)
    else if (TOKENS.has(c)) v = TOKENS.get(c)
    else v = c
    this.stack.delete(key)
    this.memo.set(key, v)
    return v
  }

  /** Expands a range into its cell values. */
  rangeValues(n) {
    if (!n.a || !n.b) return [E.ref]
    const out = []
    for (let c = Math.min(n.a.col, n.b.col); c <= Math.max(n.a.col, n.b.col); c++)
      for (let r = Math.min(n.a.row, n.b.row); r <= Math.max(n.a.row, n.b.row); r++)
