  }

  ev(n) {
    switch (n.k) {
      case 'num': return n.v
      case 'bool': return n.v
      case 'paren': return this.ev(n.e)
      case 'ref': return n.a ? this.valueOf(n.a.key) : E.ref
      case 'range': return E.err
      case 'un': {
        const v = this.ev(n.e)
        if (v instanceof Err) return v
        const x = num(v)
